def refine_topic_linkage(d):
 for dom in d['domains']:
  for n in dom['items']:
   if n['id']=='X-07':
    assert n['implementation']=='模拟部分覆盖'
    n['gap']=n['gap'].split(' '+MARKER)[0]+' '+MARKER+STATUS
 for p in d['page_blueprints']:
  if p['id'] in ('P03','P13','P16'):p['status']=p['status'].split(' '+MARKER)[0]+' '+MARKER+STATUS
 f=d['framework'];f['presentation']=[r for r in f['presentation'] if r[0]!=ROW[0]]+[list(ROW)];f['surfaces']=[s for s in f['surfaces'] if s['href']!=SURFACE['href']]+[dict(SURFACE)]
 return d
def remove_exact_increment(d):
 for dom in d['domains']:
  for n in dom['items']:
   if n['id']=='X-07':
    assert n['gap']==PRIOR+' '+MARKER+STATUS
    n['gap']=PRIOR
 for p in d['page_blueprints']:
  if p['id'] in ('P03','P13','P16'):
   suffix=' '+MARKER+STATUS;assert p['status'].endswith(suffix);p['status']=p['status'][:-len(suffix)]
 f=d['framework'];assert [r for r in f['presentation'] if r[0]==ROW[0]]==[ROW];f['presentation']=[r for r in f['presentation'] if r[0]!=ROW[0]]
 assert [s for s in f['surfaces'] if s['href']==SURFACE['href']]==[SURFACE];f['surfaces']=[s for s in f['surfaces'] if s['href']!=SURFACE['href']]
 return d
